-- Упражнения книги 19, глава 32 (Администрирование Linux). Файл строит автор-скрипт (не в репозитории); после правок можно редактировать и вручную.

INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 32, 'la32-audit-events', 0, 'func', 'События audit.log', 'text - фрагмент /var/log/audit/audit.log. Запись выглядит так: type=ТИП msg=audit(СЕКУНДЫ.МИЛЛИСЕКУНДЫ:НОМЕР): поля. Записи с одинаковыми СЕКУНДЫ.МИЛЛИСЕКУНДЫ:НОМЕР образуют одно событие (они не обязаны идти подряд). Напишите функцию parse_audit(text): верните список словарей, по одному на событие, в порядке первого появления. Ключи: id (строка ''СЕКУНДЫ.МИЛЛИСЕКУНДЫ:НОМЕР''), time (секунды, int), types (список типов записей в порядке появления, повторы сохраняются), key, comm, exe (из записи SYSCALL, иначе None), auid (число из SYSCALL; None, если поля нет или оно равно 4294967295), success (строка ''yes'' или ''no'' из SYSCALL, иначе None), paths (значения name из записей PATH по порядку, значение (null) пропускайте), cmd (расшифрованный proctitle или None). Значения в кавычках берите без кавычек. Значение без кавычек в полях comm, exe, key, name и proctitle - это hex-запись байтов UTF-8: расшифруйте её; для proctitle нулевые байты разделяют аргументы, замените их пробелами. Значение (null) означает None. Поля находите так: имя, знак =, затем значение в кавычках (внутри могут быть пробелы) или до пробела. Перед разбором уберите в начале строки префикс ''node=ИМЯ '', если он есть. Строки, не похожие на запись audit, и пустые строки пропускайте. Перед двоеточием может стоять пробел: ''audit(...) : proctitle=...'' - это тоже запись.', 'def parse_audit(text):
    pass
', 're.match для заголовка записи, re.findall(r''(\w+)=("[^"]*"|\S*)'', body) для полей; события храните в словаре и отдельно список порядка. bytes.fromhex и split(b''\x00'').', '{"func": "parse_audit", "tests": [{"args": ["type=SYSCALL msg=audit(1699000100.101:7001): arch=c000003e syscall=257 success=yes exit=3 a0=ffffff9c a1=7ffd1c2b3a40 a2=241 a3=1b6 items=2 ppid=2201 pid=2250 auid=1000 uid=0 gid=0 euid=0 suid=0 fsuid=0 egid=0 sgid=0 fsgid=0 tty=pts0 ses=3 comm=\"vim\" exe=\"/usr/bin/vim.basic\" subj=unconfined key=\"passwd_changes\"\ntype=CWD msg=audit(1699000100.101:7001): cwd=\"/home/alice\"\ntype=PATH msg=audit(1699000100.101:7001): item=0 name=\"/etc/\" inode=131073 dev=fd:00 mode=0100644 ouid=0 ogid=0 rdev=00:00 nametype=PARENT cap_fp=0 cap_fi=0 cap_fe=0 cap_fver=0 cap_frootid=0\ntype=PATH msg=audit(1699000100.101:7001): item=1 name=\"/etc/passwd\" inode=131107 dev=fd:00 mode=0100644 ouid=0 ogid=0 rdev=00:00 nametype=NORMAL cap_fp=0 cap_fi=0 cap_fe=0 cap_fver=0 cap_frootid=0\ntype=PROCTITLE msg=audit(1699000100.101:7001): proctitle=76696D002F6574632F706173737764\n"], "expected": [{"id": "1699000100.101:7001", "time": 1699000100, "types": ["SYSCALL", "CWD", "PATH", "PATH", "PROCTITLE"], "key": "passwd_changes", "comm": "vim", "exe": "/usr/bin/vim.basic", "auid": 1000, "success": "yes", "paths": ["/etc/", "/etc/passwd"], "cmd": "vim /etc/passwd"}]}, {"args": ["type=DAEMON_START msg=audit(1699000000.001:1): op=start ver=3.0.9 format=enriched kernel=5.14.0 auid=4294967295 pid=702 uid=0 ses=4294967295 subj=system_u:system_r:auditd_t:s0 res=success\ntype=SYSCALL msg=audit(1699000200.500:7050): arch=c000003e syscall=2 success=no exit=-13 a0=ffffff9c a1=7ffd1c2b3a40 a2=241 a3=1b6 items=2 ppid=2201 pid=2250 auid=4294967295 uid=0 gid=0 euid=0 suid=0 fsuid=0 egid=0 sgid=0 fsgid=0 tty=pts0 ses=3 comm=\"cat\" exe=\"/usr/bin/cat\" subj=unconfined key=(null)\ntype=CWD msg=audit(1699000200.500:7050):  cwd=\"/var/lib/app\"\ntype=PATH msg=audit(1699000200.500:7050): item=0 name=\"/etc/ssh/sshd_config\" inode=409248 dev=fd:00 mode=0100644 ouid=0 ogid=0 rdev=00:00 nametype=UNKNOWN cap_fp=0 cap_fi=0 cap_fe=0 cap_fver=0 cap_frootid=0\ntype=PROCTITLE msg=audit(1699000200.500:7050) : proctitle=636174002F6574632F7373682F737368645F636F6E666967\nthis line is not an audit record\n\n"], "expected": [{"id": "1699000000.001:1", "time": 1699000000, "types": ["DAEMON_START"], "key": null, "comm": null, "exe": null, "auid": null, "success": null, "paths": [], "cmd": null}, {"id": "1699000200.500:7050", "time": 1699000200, "types": ["SYSCALL", "CWD", "PATH", "PROCTITLE"], "key": null, "comm": "cat", "exe": "/usr/bin/cat", "auid": null, "success": "no", "paths": ["/etc/ssh/sshd_config"], "cmd": "cat /etc/ssh/sshd_config"}]}, {"args": ["node=kvm01 type=SYSCALL msg=audit(1699000300.010:8000): arch=c000003e syscall=82 success=yes exit=0 a0=ffffff9c a1=7ffd1c2b3a40 a2=241 a3=1b6 items=2 ppid=2201 pid=2250 auid=0 uid=0 gid=0 euid=0 suid=0 fsuid=0 egid=0 sgid=0 fsgid=0 tty=pts0 ses=3 comm=\"mv\" exe=\"/usr/bin/mv\" subj=unconfined key=\"cfg\"\nnode=kvm01 type=PATH msg=audit(1699000300.010:8000): item=0 name=2F6574632F6D7920636F6E662F6E65772066696C65 inode=1 dev=fd:00 mode=0100644 ouid=0 ogid=0 rdev=00:00 nametype=DELETE cap_fp=0 cap_fi=0 cap_fe=0 cap_fver=0 cap_frootid=0\nnode=kvm01 type=PATH msg=audit(1699000300.010:8000): item=1 name=\"/etc/conf\" inode=2 dev=fd:00 mode=0100644 ouid=0 ogid=0 rdev=00:00 nametype=CREATE cap_fp=0 cap_fi=0 cap_fe=0 cap_fver=0 cap_frootid=0\nnode=kvm01 type=PROCTITLE msg=audit(1699000300.010:8000): proctitle=6D76002F6574632F6D7920636F6E662F6E65772066696C65002F6574632F636F6E66\n"], "expected": [{"id": "1699000300.010:8000", "time": 1699000300, "types": ["SYSCALL", "PATH", "PATH", "PROCTITLE"], "key": "cfg", "comm": "mv", "exe": "/usr/bin/mv", "auid": 0, "success": "yes", "paths": ["/etc/my conf/new file", "/etc/conf"], "cmd": "mv /etc/my conf/new file /etc/conf"}]}, {"args": ["type=SYSCALL msg=audit(1699000400.001:9001): arch=c000003e syscall=87 success=yes exit=3 a0=ffffff9c a1=7ffd1c2b3a40 a2=241 a3=1b6 items=2 ppid=2201 pid=2250 auid=1001 uid=0 gid=0 euid=0 suid=0 fsuid=0 egid=0 sgid=0 fsgid=0 tty=pts0 ses=3 comm=6D7920746F6F6C exe=\"/usr/local/bin/my tool\" subj=unconfined key=746D70207761746368\ntype=SYSCALL msg=audit(1699000400.002:9002): arch=c000003e syscall=263 success=no exit=-1 a0=ffffff9c a1=7ffd1c2b3a40 a2=241 a3=1b6 items=2 ppid=2201 pid=2250 auid=1001 uid=0 gid=0 euid=0 suid=0 fsuid=0 egid=0 sgid=0 fsgid=0 tty=pts0 ses=3 comm=\"rm\" exe=\"/usr/bin/rm\" subj=unconfined key=\"tmp_watch\"\ntype=PATH msg=audit(1699000400.002:9002): item=0 name=\"/tmp/x\" inode=77 dev=fd:00 mode=0100644 ouid=0 ogid=0 rdev=00:00 nametype=NORMAL cap_fp=0 cap_fi=0 cap_fe=0 cap_fver=0 cap_frootid=0\ntype=PATH msg=audit(1699000400.001:9001): item=0 name=(null) inode=78 dev=fd:00 mode=0100644 ouid=0 ogid=0 rdev=00:00 nametype=UNKNOWN cap_fp=0 cap_fi=0 cap_fe=0 cap_fver=0 cap_frootid=0\ntype=PATH msg=audit(1699000400.001:9001): item=1 name=\"/tmp/y\" inode=79 dev=fd:00 mode=0100644 ouid=0 ogid=0 rdev=00:00 nametype=NORMAL cap_fp=0 cap_fi=0 cap_fe=0 cap_fver=0 cap_frootid=0\ntype=PROCTITLE msg=audit(1699000400.001:9001): proctitle=6D7920746F6F6C002D76\n"], "expected": [{"id": "1699000400.001:9001", "time": 1699000400, "types": ["SYSCALL", "PATH", "PATH", "PROCTITLE"], "key": "tmp watch", "comm": "my tool", "exe": "/usr/local/bin/my tool", "auid": 1001, "success": "yes", "paths": ["/tmp/y"], "cmd": "my tool -v"}, {"id": "1699000400.002:9002", "time": 1699000400, "types": ["SYSCALL", "PATH"], "key": "tmp_watch", "comm": "rm", "exe": "/usr/bin/rm", "auid": 1001, "success": "no", "paths": ["/tmp/x"], "cmd": null}]}, {"args": ["type=USER_LOGIN msg=audit(1699000500.100:9100): pid=3001 uid=0 auid=1000 ses=7 subj=unconfined msg=''op=login id=1000 exe=\"/usr/sbin/sshd\" hostname=203.0.113.9 addr=203.0.113.9 terminal=/dev/pts/1 res=success''\ntype=SYSCALL msg=audit(1699000500.200:9101): arch=c000003e syscall=59 success=yes exit=0 a0=ffffff9c a1=7ffd1c2b3a40 a2=241 a3=1b6 items=2 ppid=2201 pid=2250 auid=1000 uid=0 gid=0 euid=0 suid=0 fsuid=0 egid=0 sgid=0 fsgid=0 tty=pts0 ses=3 comm=\"sudo\" exe=\"/usr/bin/sudo\" subj=unconfined key=\"exec_root\"\ntype=EXECVE msg=audit(1699000500.200:9101): argc=3 a0=\"sudo\" a1=\"-i\" a2=\"id\"\ntype=PROCTITLE msg=audit(1699000500.200:9101): proctitle=7375646F002D69006964\n"], "expected": [{"id": "1699000500.100:9100", "time": 1699000500, "types": ["USER_LOGIN"], "key": null, "comm": null, "exe": null, "auid": null, "success": null, "paths": [], "cmd": null}, {"id": "1699000500.200:9101", "time": 1699000500, "types": ["SYSCALL", "EXECVE", "PROCTITLE"], "key": "exec_root", "comm": "sudo", "exe": "/usr/bin/sudo", "auid": 1000, "success": "yes", "paths": [], "cmd": "sudo -i id"}]}, {"args": ["type=SYSCALL msg=audit(1699000100.101:7001): arch=c000003e syscall=257 success=yes exit=3 a0=ffffff9c a1=7ffd1c2b3a40 a2=241 a3=1b6 items=2 ppid=2201 pid=2250 auid=1000 uid=0 gid=0 euid=0 suid=0 fsuid=0 egid=0 sgid=0 fsgid=0 tty=pts0 ses=3 comm=\"vim\" exe=\"/usr/bin/vim.basic\" subj=unconfined key=\"passwd_changes\"\ntype=CWD msg=audit(1699000100.101:7001): cwd=\"/home/alice\"\ntype=PATH msg=audit(1699000100.101:7001): item=0 name=\"/etc/\" inode=131073 dev=fd:00 mode=0100644 ouid=0 ogid=0 rdev=00:00 nametype=PARENT cap_fp=0 cap_fi=0 cap_fe=0 cap_fver=0 cap_frootid=0\ntype=PATH msg=audit(1699000100.101:7001): item=1 name=\"/etc/passwd\" inode=131107 dev=fd:00 mode=0100644 ouid=0 ogid=0 rdev=00:00 nametype=NORMAL cap_fp=0 cap_fi=0 cap_fe=0 cap_fver=0 cap_frootid=0\ntype=PROCTITLE msg=audit(1699000100.101:7001): proctitle=76696D002F6574632F706173737764\ntype=DAEMON_START msg=audit(1699000000.001:1): op=start ver=3.0.9 format=enriched kernel=5.14.0 auid=4294967295 pid=702 uid=0 ses=4294967295 subj=system_u:system_r:auditd_t:s0 res=success\ntype=SYSCALL msg=audit(1699000200.500:7050): arch=c000003e syscall=2 success=no exit=-13 a0=ffffff9c a1=7ffd1c2b3a40 a2=241 a3=1b6 items=2 ppid=2201 pid=2250 auid=4294967295 uid=0 gid=0 euid=0 suid=0 fsuid=0 egid=0 sgid=0 fsgid=0 tty=pts0 ses=3 comm=\"cat\" exe=\"/usr/bin/cat\" subj=unconfined key=(null)\ntype=CWD msg=audit(1699000200.500:7050):  cwd=\"/var/lib/app\"\ntype=PATH msg=audit(1699000200.500:7050): item=0 name=\"/etc/ssh/sshd_config\" inode=409248 dev=fd:00 mode=0100644 ouid=0 ogid=0 rdev=00:00 nametype=UNKNOWN cap_fp=0 cap_fi=0 cap_fe=0 cap_fver=0 cap_frootid=0\ntype=PROCTITLE msg=audit(1699000200.500:7050) : proctitle=636174002F6574632F7373682F737368645F636F6E666967\nthis line is not an audit record\n\n"], "expected": [{"id": "1699000100.101:7001", "time": 1699000100, "types": ["SYSCALL", "CWD", "PATH", "PATH", "PROCTITLE"], "key": "passwd_changes", "comm": "vim", "exe": "/usr/bin/vim.basic", "auid": 1000, "success": "yes", "paths": ["/etc/", "/etc/passwd"], "cmd": "vim /etc/passwd"}, {"id": "1699000000.001:1", "time": 1699000000, "types": ["DAEMON_START"], "key": null, "comm": null, "exe": null, "auid": null, "success": null, "paths": [], "cmd": null}, {"id": "1699000200.500:7050", "time": 1699000200, "types": ["SYSCALL", "CWD", "PATH", "PROCTITLE"], "key": null, "comm": "cat", "exe": "/usr/bin/cat", "auid": null, "success": "no", "paths": ["/etc/ssh/sshd_config"], "cmd": "cat /etc/ssh/sshd_config"}]}, {"args": [""], "expected": []}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 32, 'la32-avc-classify', 1, 'func', 'Классификатор отказов SELinux', 'text - фрагмент audit.log. Записи типов AVC и USER_AVC с текстом ''avc:  denied  { права }'' - это отказы (granted и записи других типов пропускайте). Напишите функцию classify_avc(text, booleans, port_types). booleans - список [имя, тип_субъекта, тип_объекта, класс, право]; port_types - словарь тип_субъекта -> тип порта. Для отказа возьмите: права - отсортированный список слов из скобок; comm (в кавычках, без кавычек; без кавычек - hex-запись UTF-8, расшифруйте); stype и ttype - третья часть scontext и tcontext (тип); tclass; permissive - True, если permissive=1. Причину и исправление выбирайте по первому подходящему правилу: 1) в booleans есть строка с теми же stype, ttype и tclass, а её право входит в права отказа - cause ''boolean'', fix ''setsebool:ИМЯ''. 2) tclass равен tcp_socket или udp_socket, в правах есть name_bind или name_connect и stype есть в port_types - cause ''port'', fix ''semanage-port:ТИП_ПОРТА:ПОРТ'', где ПОРТ - поле src при name_bind и поле dest при name_connect (если есть оба права, берите name_bind), строкой как в записи. 3) tclass один из file, dir, lnk_file, sock_file, fifo_file, chr_file, blk_file, а ttype один из default_t, unlabeled_t, user_home_t, tmp_t, var_t, mnt_t - cause ''label'', fix ''restorecon''. 4) иначе cause ''policy'', fix ''module''. Одинаковые отказы (одни и те же comm, stype, ttype, tclass, права, permissive, cause и fix) объедините, увеличивая count; порядок - по первому появлению. Элемент результата: {''comm'',''stype'',''ttype'',''tclass'',''perms'',''permissive'',''cause'',''fix'',''count''}. Значение поля в записи читайте как имя=значение (в кавычках или до пробела); у USER_AVC весь текст лежит в msg=''...'': кавычки-апострофы по краям значений отбрасывайте.', 'def classify_avc(text, booleans, port_types):
    pass
