INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 32, 'la32-apparmor-denials', 2, 'func', 'Отказы AppArmor из журнала', 'text - строки журнала ядра (dmesg, journalctl -k или audit.log), часть из них - сообщения AppArmor вида apparmor="DENIED" operation="open" profile="..." name="..." ... requested_mask="r" denied_mask="r". Напишите функцию apparmor_report(text): рассматривайте только строки, где есть apparmor="DENIED", apparmor="ALLOWED" (режим complain) или apparmor="AUDIT"; остальные (в том числе apparmor="STATUS") пропускайте. Поля читайте как имя=значение (значение в кавычках - без кавычек, в нём могут быть пробелы - или до пробела). Цель строки: значение name; если его нет, значение capname; если нет и его, но есть family, то ''family/sock_type'' (sock_type пустой, если его нет); иначе пустая строка. Сгруппируйте строки по (profile, operation, цель, статус) и верните список [profile, operation, цель, статус, количество, маски]. Маски - различные значения denied_mask группы, по алфавиту, через запятую без пробелов (пустая строка, если поля denied_mask нет). Отсортируйте список по количеству по убыванию, при равенстве по profile, operation, цели и статусу по алфавиту.', 'def apparmor_report(text):
    pass
', 're.findall(r''(\w+)=("[^"]*"|\S*)'', line); ключ группы - кортеж из четырёх полей, значение - счётчик и множество значений масок.', '{"func": "apparmor_report", "tests": [{"args": ["[1521056.552037] audit: type=1400 audit(1571868402.378:24425): apparmor=\"DENIED\" operation=\"open\" profile=\"/usr/sbin/cups-browsed\" name=\"/var/lib/libvirt/dnsmasq/\" pid=1128 comm=\"cups-browsed\" requested_mask=\"r\" denied_mask=\"r\" fsuid=0 ouid=0\n[1521057.100000] audit: type=1400 audit(1571868403.001:24426): apparmor=\"DENIED\" operation=\"open\" profile=\"/usr/sbin/cups-browsed\" name=\"/var/lib/libvirt/dnsmasq/\" pid=1128 comm=\"cups-browsed\" requested_mask=\"r\" denied_mask=\"r\" fsuid=0 ouid=0\n[1521058.000000] audit: type=1400 audit(1571868404.001:24427): apparmor=\"DENIED\" operation=\"mknod\" profile=\"/usr/sbin/cups-browsed\" name=\"/var/lib/libvirt/dnsmasq/x\" pid=1128 comm=\"cups-browsed\" requested_mask=\"c\" denied_mask=\"c\" fsuid=0 ouid=0\n[1521059.000000] eth0: link up\n"], "expected": [["/usr/sbin/cups-browsed", "open", "/var/lib/libvirt/dnsmasq/", "DENIED", 2, "r"], ["/usr/sbin/cups-browsed", "mknod", "/var/lib/libvirt/dnsmasq/x", "DENIED", 1, "c"]]}, {"args": ["Nov  3 10:00:01 kvm01 kernel: audit: type=1400 audit(1699000001.100:301): apparmor=\"ALLOWED\" operation=\"open\" profile=\"libvirt-4a1b2c3d-1111-2222-3333-444455556666\" name=\"/srv/images/web01.qcow2\" pid=2210 comm=\"qemu-system-x86\" requested_mask=\"wr\" denied_mask=\"wr\" fsuid=64055 ouid=64055\nNov  3 10:00:02 kvm01 kernel: audit: type=1400 audit(1699000002.100:302): apparmor=\"ALLOWED\" operation=\"open\" profile=\"libvirt-4a1b2c3d-1111-2222-3333-444455556666\" name=\"/srv/images/web01.qcow2\" pid=2210 comm=\"qemu-system-x86\" requested_mask=\"r\" denied_mask=\"r\" fsuid=64055 ouid=64055\nNov  3 10:00:03 kvm01 kernel: audit: type=1400 audit(1699000003.100:303): apparmor=\"DENIED\" operation=\"capable\" profile=\"/usr/sbin/tcpdump\" pid=2300 comm=\"tcpdump\" capability=12  capname=\"net_admin\"\nNov  3 10:00:04 kvm01 kernel: audit: type=1400 audit(1699000004.100:304): apparmor=\"DENIED\" operation=\"create\" profile=\"/usr/sbin/tcpdump\" pid=2300 comm=\"tcpdump\" family=\"inet\" sock_type=\"stream\" protocol=6 requested_mask=\"create\" denied_mask=\"create\"\nNov  3 10:00:05 kvm01 kernel: audit: type=1400 audit(1699000005.100:305): apparmor=\"STATUS\" operation=\"profile_replace\" info=\"same as current profile, skipping\" profile=\"unconfined\" name=\"libvirt-4a1b2c3d-1111-2222-3333-444455556666\" pid=2400 comm=\"apparmor_parser\"\nNov  3 10:00:06 kvm01 kernel: audit: type=1400 audit(1699000006.100:306): apparmor=\"AUDIT\" operation=\"exec\" profile=\"/usr/bin/man\" name=\"/usr/bin/less\" pid=2500 comm=\"man\" requested_mask=\"x\" fsuid=1000 ouid=0 target=\"/usr/bin/man//less\"\n"], "expected": [["libvirt-4a1b2c3d-1111-2222-3333-444455556666", "open", "/srv/images/web01.qcow2", "ALLOWED", 2, "r,wr"], ["/usr/bin/man", "exec", "/usr/bin/less", "AUDIT", 1, ""], ["/usr/sbin/tcpdump", "capable", "net_admin", "DENIED", 1, ""], ["/usr/sbin/tcpdump", "create", "inet/stream", "DENIED", 1, "create"]]}, {"args": ["type=AVC msg=audit(1699000100.200:410): apparmor=\"DENIED\" operation=\"exec\" profile=\"snap.foo.bar\" name=\"/usr/bin/my tool\" pid=100 comm=\"bar\" requested_mask=\"x\" denied_mask=\"x\" fsuid=1000 ouid=0\ntype=AVC msg=audit(1699000100.300:411): apparmor=\"DENIED\" operation=\"exec\" profile=\"snap.foo.bar\" name=\"/usr/bin/my tool\" pid=100 comm=\"bar\" requested_mask=\"x\" denied_mask=\"x\" fsuid=1000 ouid=0\ntype=AVC msg=audit(1699000100.400:412): apparmor=\"DENIED\" operation=\"file_lock\" profile=\"/usr/sbin/mysqld\" name=\"/var/lib/mysql/ib_logfile0\" pid=200 comm=\"mysqld\" requested_mask=\"k\" denied_mask=\"k\" fsuid=110 ouid=110\ntype=AVC msg=audit(1699000100.500:413): apparmor=\"DENIED\" operation=\"open\" profile=\"/usr/sbin/mysqld\" name=\"/var/lib/mysql/ib_logfile0\" pid=200 comm=\"mysqld\" requested_mask=\"rw\" denied_mask=\"w\" fsuid=110 ouid=110\ntype=AVC msg=audit(1699000100.600:414): apparmor=\"DENIED\" operation=\"open\" profile=\"/usr/sbin/mysqld\" name=\"/var/lib/mysql/ib_logfile0\" pid=200 comm=\"mysqld\" requested_mask=\"rw\" denied_mask=\"r\" fsuid=110 ouid=110\n"], "expected": [["/usr/sbin/mysqld", "open", "/var/lib/mysql/ib_logfile0", "DENIED", 2, "r,w"], ["snap.foo.bar", "exec", "/usr/bin/my tool", "DENIED", 2, "x"], ["/usr/sbin/mysqld", "file_lock", "/var/lib/mysql/ib_logfile0", "DENIED", 1, "k"]]}, {"args": ["[1521056.552037] audit: type=1400 audit(1571868402.378:24425): apparmor=\"DENIED\" operation=\"open\" profile=\"/usr/sbin/cups-browsed\" name=\"/var/lib/libvirt/dnsmasq/\" pid=1128 comm=\"cups-browsed\" requested_mask=\"r\" denied_mask=\"r\" fsuid=0 ouid=0\n[1521057.100000] audit: type=1400 audit(1571868403.001:24426): apparmor=\"DENIED\" operation=\"open\" profile=\"/usr/sbin/cups-browsed\" name=\"/var/lib/libvirt/dnsmasq/\" pid=1128 comm=\"cups-browsed\" requested_mask=\"r\" denied_mask=\"r\" fsuid=0 ouid=0\n[1521058.000000] audit: type=1400 audit(1571868404.001:24427): apparmor=\"DENIED\" operation=\"mknod\" profile=\"/usr/sbin/cups-browsed\" name=\"/var/lib/libvirt/dnsmasq/x\" pid=1128 comm=\"cups-browsed\" requested_mask=\"c\" denied_mask=\"c\" fsuid=0 ouid=0\n[1521059.000000] eth0: link up\nNov  3 10:00:01 kvm01 kernel: audit: type=1400 audit(1699000001.100:301): apparmor=\"ALLOWED\" operation=\"open\" profile=\"libvirt-4a1b2c3d-1111-2222-3333-444455556666\" name=\"/srv/images/web01.qcow2\" pid=2210 comm=\"qemu-system-x86\" requested_mask=\"wr\" denied_mask=\"wr\" fsuid=64055 ouid=64055\nNov  3 10:00:02 kvm01 kernel: audit: type=1400 audit(1699000002.100:302): apparmor=\"ALLOWED\" operation=\"open\" profile=\"libvirt-4a1b2c3d-1111-2222-3333-444455556666\" name=\"/srv/images/web01.qcow2\" pid=2210 comm=\"qemu-system-x86\" requested_mask=\"r\" denied_mask=\"r\" fsuid=64055 ouid=64055\nNov  3 10:00:03 kvm01 kernel: audit: type=1400 audit(1699000003.100:303): apparmor=\"DENIED\" operation=\"capable\" profile=\"/usr/sbin/tcpdump\" pid=2300 comm=\"tcpdump\" capability=12  capname=\"net_admin\"\nNov  3 10:00:04 kvm01 kernel: audit: type=1400 audit(1699000004.100:304): apparmor=\"DENIED\" operation=\"create\" profile=\"/usr/sbin/tcpdump\" pid=2300 comm=\"tcpdump\" family=\"inet\" sock_type=\"stream\" protocol=6 requested_mask=\"create\" denied_mask=\"create\"\nNov  3 10:00:05 kvm01 kernel: audit: type=1400 audit(1699000005.100:305): apparmor=\"STATUS\" operation=\"profile_replace\" info=\"same as current profile, skipping\" profile=\"unconfined\" name=\"libvirt-4a1b2c3d-1111-2222-3333-444455556666\" pid=2400 comm=\"apparmor_parser\"\nNov  3 10:00:06 kvm01 kernel: audit: type=1400 audit(1699000006.100:306): apparmor=\"AUDIT\" operation=\"exec\" profile=\"/usr/bin/man\" name=\"/usr/bin/less\" pid=2500 comm=\"man\" requested_mask=\"x\" fsuid=1000 ouid=0 target=\"/usr/bin/man//less\"\ntype=AVC msg=audit(1699000100.200:410): apparmor=\"DENIED\" operation=\"exec\" profile=\"snap.foo.bar\" name=\"/usr/bin/my tool\" pid=100 comm=\"bar\" requested_mask=\"x\" denied_mask=\"x\" fsuid=1000 ouid=0\ntype=AVC msg=audit(1699000100.300:411): apparmor=\"DENIED\" operation=\"exec\" profile=\"snap.foo.bar\" name=\"/usr/bin/my tool\" pid=100 comm=\"bar\" requested_mask=\"x\" denied_mask=\"x\" fsuid=1000 ouid=0\ntype=AVC msg=audit(1699000100.400:412): apparmor=\"DENIED\" operation=\"file_lock\" profile=\"/usr/sbin/mysqld\" name=\"/var/lib/mysql/ib_logfile0\" pid=200 comm=\"mysqld\" requested_mask=\"k\" denied_mask=\"k\" fsuid=110 ouid=110\ntype=AVC msg=audit(1699000100.500:413): apparmor=\"DENIED\" operation=\"open\" profile=\"/usr/sbin/mysqld\" name=\"/var/lib/mysql/ib_logfile0\" pid=200 comm=\"mysqld\" requested_mask=\"rw\" denied_mask=\"w\" fsuid=110 ouid=110\ntype=AVC msg=audit(1699000100.600:414): apparmor=\"DENIED\" operation=\"open\" profile=\"/usr/sbin/mysqld\" name=\"/var/lib/mysql/ib_logfile0\" pid=200 comm=\"mysqld\" requested_mask=\"rw\" denied_mask=\"r\" fsuid=110 ouid=110\n"], "expected": [["/usr/sbin/cups-browsed", "open", "/var/lib/libvirt/dnsmasq/", "DENIED", 2, "r"], ["/usr/sbin/mysqld", "open", "/var/lib/mysql/ib_logfile0", "DENIED", 2, "r,w"], ["libvirt-4a1b2c3d-1111-2222-3333-444455556666", "open", "/srv/images/web01.qcow2", "ALLOWED", 2, "r,wr"], ["snap.foo.bar", "exec", "/usr/bin/my tool", "DENIED", 2, "x"], ["/usr/bin/man", "exec", "/usr/bin/less", "AUDIT", 1, ""], ["/usr/sbin/cups-browsed", "mknod", "/var/lib/libvirt/dnsmasq/x", "DENIED", 1, "c"], ["/usr/sbin/mysqld", "file_lock", "/var/lib/mysql/ib_logfile0", "DENIED", 1, "k"], ["/usr/sbin/tcpdump", "capable", "net_admin", "DENIED", 1, ""], ["/usr/sbin/tcpdump", "create", "inet/stream", "DENIED", 1, "create"]]}, {"args": [""], "expected": []}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 32, 'la32-hardening-check', 3, 'func', 'Проверка укрепления хоста', 'Напишите функцию hardening(sshd_t, sudoers, sysctl): sshd_t - вывод sshd -T (строки ''ключ значение'', ключи строчные), sudoers - текст /etc/sudoers, sysctl - строки ''ключ = значение'' (вывод sysctl -a). Верните список находок [идентификатор, серьёзность, объект], отсортированный по серьёзности (high, medium, low), затем по идентификатору и объекту. Находка не повторяется. SSH (значения сравнивайте в нижнем регистре; для каждого ключа берите первую строку; отсутствующий ключ находки не даёт, кроме последней проверки): ssh-root-login high, если permitrootlogin равен yes; ssh-empty-passwords high, если permitemptypasswords равен yes; ssh-password-auth medium, если passwordauthentication равен yes; ssh-max-auth-tries low, если maxauthtries больше 4 (объект - значение); ssh-x11 low, если x11forwarding равен yes; ssh-no-allowlist low, если нет ни одной строки allowusers и allowgroups (объект ''-''). Для остальных находок SSH объект - значение ''yes''. sudoers: склейте строки, оканчивающиеся на обратную косую черту, пробелом; пропускайте строки-комментарии (начинающиеся с #, в том числе #include), строки User_Alias, Runas_Alias, Host_Alias, Cmnd_Alias и строки, не похожие на ''кто хосты=правило'' (вокруг = могут стоять пробелы). Строка Defaults с ''!authenticate'' даёт sudo-no-authenticate high (объект ''Defaults''). В правиле ''кто хосты=(кто запускает) список'' список делится запятыми; в начале элемента могут стоять теги NOPASSWD:, PASSWD:, SETENV:, NOSETENV:, NOEXEC:, EXEC:, LOG_INPUT:, LOG_OUTPUT: - теги NOPASSWD и PASSWD действуют на этот элемент и все следующие, пока не сменятся. Элемент ALL: если при нём действует NOPASSWD - sudo-nopasswd-all high (объект - кто); иначе, если кто не в {root, %wheel, %sudo, %admin} - sudo-all medium. Если у правила есть оба вида ALL, берётся только sudo-nopasswd-all. Элемент, у которого первое слово (без каталога) одно из bash, sh, zsh, vi, vim, less, more, man, find, awk, python, python3, perl - sudo-shell-escape medium (объект - кто). Правила пользователя root находок не дают. sysctl (нужны ключи из строк; отсутствующий ключ находки не даёт; значение - целое): kernel.dmesg_restrict должен быть 1 (sysctl-dmesg-restrict, low); kernel.kptr_restrict не меньше 1 (sysctl-kptr-restrict, medium); kernel.randomize_va_space равен 2 (sysctl-aslr, medium); net.ipv4.conf.all.rp_filter равен 1 или 2 (sysctl-rp-filter, medium); net.ipv4.conf.all.accept_redirects равен 0 (sysctl-accept-redirects, medium); fs.protected_hardlinks равен 1 (sysctl-protected-hardlinks, medium); fs.protected_symlinks равен 1 (sysctl-protected-symlinks, medium); kernel.yama.ptrace_scope не меньше 1 (sysctl-ptrace-scope, low); kernel.unprivileged_bpf_disabled не меньше 1 (sysctl-unpriv-bpf, medium). Объект находки sysctl - значение строкой, как в тексте.', 'def hardening(sshd_t, sudoers, sysctl):
    pass
', 'Три независимые части складывайте в множество кортежей; в конце sorted с ключом (ранг серьёзности, id, объект). Теги sudoers отслеживайте переменной, которую элементы списка меняют по порядку.', '{"func": "hardening", "tests": [{"args": ["port 22\naddressfamily any\nlistenaddress 0.0.0.0:22\nlogingracetime 120\npermitrootlogin yes\nmaxauthtries 6\npubkeyauthentication yes\npasswordauthentication yes\npermitemptypasswords no\nkbdinteractiveauthentication no\nusepam yes\nx11forwarding yes\nclientaliveinterval 0\n", "# User privilege specification\nroot    ALL=(ALL:ALL) ALL\n\nDefaults\tenv_reset\nDefaults\tsecure_path=\"/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin\"\n%admin ALL=(ALL) ALL\n%sudo\tALL=(ALL:ALL) ALL\n@includedir /etc/sudoers.d\n", "kernel.dmesg_restrict = 0\nkernel.kptr_restrict = 0\nkernel.randomize_va_space = 2\nnet.ipv4.conf.all.rp_filter = 0\nnet.ipv4.conf.all.accept_redirects = 1\nfs.protected_hardlinks = 1\nfs.protected_symlinks = 0\nkernel.yama.ptrace_scope = 0\nkernel.unprivileged_bpf_disabled = 2\n"], "expected": [["ssh-root-login", "high", "yes"], ["ssh-password-auth", "medium", "yes"], ["sysctl-accept-redirects", "medium", "1"], ["sysctl-kptr-restrict", "medium", "0"], ["sysctl-protected-symlinks", "medium", "0"], ["sysctl-rp-filter", "medium", "0"], ["ssh-max-auth-tries", "low", "6"], ["ssh-no-allowlist", "low", "-"], ["ssh-x11", "low", "yes"], ["sysctl-dmesg-restrict", "low", "0"], ["sysctl-ptrace-scope", "low", "0"]]}, {"args": ["port 22\npermitrootlogin prohibit-password\nmaxauthtries 3\npasswordauthentication no\npermitemptypasswords no\nx11forwarding no\nallowusers alice\nallowusers bob\n", "# User privilege specification\nroot    ALL=(ALL:ALL) ALL\n\nDefaults\tenv_reset\nDefaults\tsecure_path=\"/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin\"\n%admin ALL=(ALL) ALL\n%sudo\tALL=(ALL:ALL) ALL\n@includedir /etc/sudoers.d\n", "kernel.dmesg_restrict = 1\nkernel.kptr_restrict = 2\nkernel.randomize_va_space = 2\nnet.ipv4.conf.all.rp_filter = 2\nnet.ipv4.conf.all.accept_redirects = 0\nfs.protected_hardlinks = 1\nfs.protected_symlinks = 1\nkernel.yama.ptrace_scope = 1\nkernel.unprivileged_bpf_disabled = 1\n"], "expected": []}, {"args": ["port 2200\npermitrootlogin without-password\nmaxauthtries 4\npasswordauthentication yes\npermitemptypasswords yes\nx11forwarding no\nallowgroups ops\n", "User_Alias ADMINS = alice, bob\nCmnd_Alias SERVICES = /usr/bin/systemctl restart nginx, /usr/bin/systemctl reload nginx\nDefaults:deploy !authenticate\nalice ALL=(ALL) NOPASSWD: ALL\nbob   ALL=(ALL) ALL\ndeploy ALL=(root) NOPASSWD: SERVICES\ncarol ALL=(root) /usr/bin/vim /etc/hosts\ndave ALL=(root) NOPASSWD: /usr/bin/journalctl -u nginx, \\\n      /usr/sbin/iptables -L\n%wheel ALL=(ALL) NOPASSWD: ALL\nerin ALL=(ALL) NOPASSWD: /usr/bin/rsync, PASSWD: ALL\nfrank ALL=(ALL) PASSWD: ALL, NOPASSWD: /usr/bin/less /var/log/syslog\n", "kernel.kptr_restrict = 1\nkernel.randomize_va_space = 1\nnet.ipv4.conf.all.rp_filter = 1\nvm.swappiness = 60\nkernel.yama.ptrace_scope = 3\n"], "expected": [["ssh-empty-passwords", "high", "yes"], ["sudo-no-authenticate", "high", "Defaults"], ["sudo-nopasswd-all", "high", "%wheel"], ["sudo-nopasswd-all", "high", "alice"], ["ssh-password-auth", "medium", "yes"], ["sudo-all", "medium", "bob"], ["sudo-all", "medium", "erin"], ["sudo-all", "medium", "frank"], ["sudo-shell-escape", "medium", "carol"], ["sudo-shell-escape", "medium", "frank"], ["sysctl-aslr", "medium", "1"]]}, {"args": ["port 22\npermitrootlogin prohibit-password\nmaxauthtries 3\npasswordauthentication no\npermitemptypasswords no\nx11forwarding no\nallowusers alice\nallowusers bob\n", "User_Alias ADMINS = alice, bob\nCmnd_Alias SERVICES = /usr/bin/systemctl restart nginx, /usr/bin/systemctl reload nginx\nDefaults:deploy !authenticate\nalice ALL=(ALL) NOPASSWD: ALL\nbob   ALL=(ALL) ALL\ndeploy ALL=(root) NOPASSWD: SERVICES\ncarol ALL=(root) /usr/bin/vim /etc/hosts\ndave ALL=(root) NOPASSWD: /usr/bin/journalctl -u nginx, \\\n      /usr/sbin/iptables -L\n%wheel ALL=(ALL) NOPASSWD: ALL\nerin ALL=(ALL) NOPASSWD: /usr/bin/rsync, PASSWD: ALL\nfrank ALL=(ALL) PASSWD: ALL, NOPASSWD: /usr/bin/less /var/log/syslog\n", ""], "expected": [["sudo-no-authenticate", "high", "Defaults"], ["sudo-nopasswd-all", "high", "%wheel"], ["sudo-nopasswd-all", "high", "alice"], ["sudo-all", "medium", "bob"], ["sudo-all", "medium", "erin"], ["sudo-all", "medium", "frank"], ["sudo-shell-escape", "medium", "carol"], ["sudo-shell-escape", "medium", "frank"]]}, {"args": ["port 22\naddressfamily any\nlistenaddress 0.0.0.0:22\nlogingracetime 120\npermitrootlogin yes\nmaxauthtries 6\npubkeyauthentication yes\npasswordauthentication yes\npermitemptypasswords no\nkbdinteractiveauthentication no\nusepam yes\nx11forwarding yes\nclientaliveinterval 0\n", "# nothing here\nbackup ALL = NOPASSWD: /usr/bin/rsync, /usr/bin/find /srv -type f\nroot ALL=(ALL) NOPASSWD: ALL\n", "kernel.dmesg_restrict = 1\nkernel.kptr_restrict = 2\nkernel.randomize_va_space = 2\nnet.ipv4.conf.all.rp_filter = 2\nnet.ipv4.conf.all.accept_redirects = 0\nfs.protected_hardlinks = 1\nfs.protected_symlinks = 1\nkernel.yama.ptrace_scope = 1\nkernel.unprivileged_bpf_disabled = 1\n"], "expected": [["ssh-root-login", "high", "yes"], ["ssh-password-auth", "medium", "yes"], ["sudo-shell-escape", "medium", "backup"], ["ssh-max-auth-tries", "low", "6"], ["ssh-no-allowlist", "low", "-"], ["ssh-x11", "low", "yes"]]}, {"args": ["", "", ""], "expected": [["ssh-no-allowlist", "low", "-"]]}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 32, 'la32-privilege-report', 4, 'func', 'Отчёт о setuid и файловых возможностях', 'find_out - вывод find / -xdev -type f \( -perm -4000 -o -perm -2000 \) -printf ''%m %u %g %p\n'': строки ''режим владелец группа путь'', режим - восьмеричные права вместе со специальными битами, путь может содержать пробелы. getcap_out - вывод getcap -r /: строка ''путь возможности'' (новый формат libcap, например ''/usr/bin/ping cap_net_raw=ep'') либо ''путь = возможности'' (старый формат, ''/usr/bin/ping = cap_net_raw+ep''); в новом формате путь - всё до последнего пробела. Возможности - один отрезок ''имя,имя=флаги'' или ''имя,имя+флаги'', флаги - буквы e, i, p (могут отсутствовать); строки другого вида пропускайте. expected - список путей, которым положено иметь такие права. Напишите функцию privilege_report(find_out, getcap_out, expected): верните список [путь, вид, подробность], отсортированный по пути, затем по виду. Виды: writable (подробность - четыре восьмеричные цифры режима, например ''4775'') - у файла есть бит setuid или setgid и право записи для группы или остальных (даже если путь ожидаем); setuid (подробность - владелец) и setgid (подробность - группа) - соответствующий бит стоит у файла, которого нет в expected; cap-dangerous (подробность - опасные возможности по алфавиту через запятую) - среди возможностей есть cap_sys_admin, cap_sys_module, cap_sys_ptrace, cap_setuid, cap_setgid, cap_dac_override, cap_dac_read_search или cap_fowner и флагов хотя бы один (даже если путь ожидаем); cap-unexpected (подробность - все возможности по алфавиту через запятую, затем ''='' и флаги в порядке e, i, p, например ''cap_net_raw=ep'') - пути нет в expected.', 'def privilege_report(find_out, getcap_out, expected):
    pass
', 'Режим int(t[0], 8); биты 0o4000, 0o2000, 0o022. Для getcap: если в строке есть '' = '' - старый формат, иначе rsplit('' '', 1).', '{"func": "privilege_report", "tests": [{"args": ["4755 root root /usr/bin/passwd\n4755 root root /usr/bin/sudo\n4755 root root /usr/bin/su\n2755 root shadow /usr/bin/chage\n2755 root crontab /usr/bin/crontab\n4750 root dip /usr/sbin/pppd\n4711 root root /opt/tools/helper\n6755 appsvc appgrp /opt/app/bin/runner\n", "/usr/bin/ping cap_net_raw=ep\n/usr/bin/mtr-packet cap_net_raw=ep\n/usr/sbin/arping cap_net_raw=p\n/opt/app/bin/web cap_net_bind_service=ep\n/usr/local/bin/pyrun cap_setuid,cap_sys_admin=ep\n/opt/vm tools/qemu-bridge-helper cap_net_admin=ep\n", ["/usr/bin/passwd", "/usr/bin/sudo", "/usr/bin/su", "/usr/bin/chage", "/usr/bin/crontab", "/usr/sbin/pppd", "/usr/bin/mount", "/usr/lib/utempter/utempter", "/usr/bin/ping", "/usr/bin/mtr-packet", "/usr/sbin/arping", "/usr/local/bin/dacview"]], "expected": [["/opt/app/bin/runner", "setgid", "appgrp"], ["/opt/app/bin/runner", "setuid", "appsvc"], ["/opt/app/bin/web", "cap-unexpected", "cap_net_bind_service=ep"], ["/opt/tools/helper", "setuid", "root"], ["/opt/vm tools/qemu-bridge-helper", "cap-unexpected", "cap_net_admin=ep"], ["/usr/local/bin/pyrun", "cap-dangerous", "cap_setuid,cap_sys_admin"], ["/usr/local/bin/pyrun", "cap-unexpected", "cap_setuid,cap_sys_admin=ep"]]}, {"args": ["4775 root root /usr/local/bin/backup.sh\n4755 root root /usr/bin/mount\n2711 root utmp /usr/lib/utempter/utempter\n4755 www-data www-data /var/www/uploads/x.php\n4755 root root /home/alice/my tool/suid shell\n0755 root root /usr/bin/harmless\n", "/usr/bin/ping = cap_net_raw+ep\n/usr/lib/gst/gst-ptp-helper = cap_net_bind_service,cap_net_admin+ep\n/usr/local/bin/dacview = cap_dac_read_search+i\n/usr/local/bin/dacview2 = cap_dac_read_search+ep\n/usr/local/bin/empty = cap_chown+\n", ["/usr/bin/passwd", "/usr/bin/sudo", "/usr/bin/su", "/usr/bin/chage", "/usr/bin/crontab", "/usr/sbin/pppd", "/usr/bin/mount", "/usr/lib/utempter/utempter", "/usr/bin/ping", "/usr/bin/mtr-packet", "/usr/sbin/arping", "/usr/local/bin/dacview"]], "expected": [["/home/alice/my tool/suid shell", "setuid", "root"], ["/usr/lib/gst/gst-ptp-helper", "cap-unexpected", "cap_net_admin,cap_net_bind_service=ep"], ["/usr/local/bin/backup.sh", "setuid", "root"], ["/usr/local/bin/backup.sh", "writable", "4775"], ["/usr/local/bin/dacview", "cap-dangerous", "cap_dac_read_search"], ["/usr/local/bin/dacview2", "cap-dangerous", "cap_dac_read_search"], ["/usr/local/bin/dacview2", "cap-unexpected", "cap_dac_read_search=ep"], ["/usr/local/bin/empty", "cap-unexpected", "cap_chown="], ["/var/www/uploads/x.php", "setuid", "www-data"]]}, {"args": ["4755 root root /usr/bin/passwd\n4755 root root /usr/bin/sudo\n4755 root root /usr/bin/su\n2755 root shadow /usr/bin/chage\n2755 root crontab /usr/bin/crontab\n4750 root dip /usr/sbin/pppd\n4711 root root /opt/tools/helper\n6755 appsvc appgrp /opt/app/bin/runner\n4775 root root /usr/local/bin/backup.sh\n4755 root root /usr/bin/mount\n2711 root utmp /usr/lib/utempter/utempter\n4755 www-data www-data /var/www/uploads/x.php\n4755 root root /home/alice/my tool/suid shell\n0755 root root /usr/bin/harmless\n", "/usr/bin/ping cap_net_raw=ep\n/usr/bin/mtr-packet cap_net_raw=ep\n/usr/sbin/arping cap_net_raw=p\n/opt/app/bin/web cap_net_bind_service=ep\n/usr/local/bin/pyrun cap_setuid,cap_sys_admin=ep\n/opt/vm tools/qemu-bridge-helper cap_net_admin=ep\n/usr/bin/ping = cap_net_raw+ep\n/usr/lib/gst/gst-ptp-helper = cap_net_bind_service,cap_net_admin+ep\n/usr/local/bin/dacview = cap_dac_read_search+i\n/usr/local/bin/dacview2 = cap_dac_read_search+ep\n/usr/local/bin/empty = cap_chown+\n", ["/usr/bin/passwd", "/usr/bin/sudo", "/usr/bin/su", "/usr/bin/chage", "/usr/bin/crontab", "/usr/sbin/pppd", "/usr/bin/mount", "/usr/lib/utempter/utempter", "/usr/bin/ping", "/usr/bin/mtr-packet", "/usr/sbin/arping", "/usr/local/bin/dacview"]], "expected": [["/home/alice/my tool/suid shell", "setuid", "root"], ["/opt/app/bin/runner", "setgid", "appgrp"], ["/opt/app/bin/runner", "setuid", "appsvc"], ["/opt/app/bin/web", "cap-unexpected", "cap_net_bind_service=ep"], ["/opt/tools/helper", "setuid", "root"], ["/opt/vm tools/qemu-bridge-helper", "cap-unexpected", "cap_net_admin=ep"], ["/usr/lib/gst/gst-ptp-helper", "cap-unexpected", "cap_net_admin,cap_net_bind_service=ep"], ["/usr/local/bin/backup.sh", "setuid", "root"], ["/usr/local/bin/backup.sh", "writable", "4775"], ["/usr/local/bin/dacview", "cap-dangerous", "cap_dac_read_search"], ["/usr/local/bin/dacview2", "cap-dangerous", "cap_dac_read_search"], ["/usr/local/bin/dacview2", "cap-unexpected", "cap_dac_read_search=ep"], ["/usr/local/bin/empty", "cap-unexpected", "cap_chown="], ["/usr/local/bin/pyrun", "cap-dangerous", "cap_setuid,cap_sys_admin"], ["/usr/local/bin/pyrun", "cap-unexpected", "cap_setuid,cap_sys_admin=ep"], ["/var/www/uploads/x.php", "setuid", "www-data"]]}, {"args": ["4755 root root /usr/bin/passwd\n4755 root root /usr/bin/sudo\n4755 root root /usr/bin/su\n2755 root shadow /usr/bin/chage\n2755 root crontab /usr/bin/crontab\n4750 root dip /usr/sbin/pppd\n4711 root root /opt/tools/helper\n6755 appsvc appgrp /opt/app/bin/runner\n", "", []], "expected": [["/opt/app/bin/runner", "setgid", "appgrp"], ["/opt/app/bin/runner", "setuid", "appsvc"], ["/opt/tools/helper", "setuid", "root"], ["/usr/bin/chage", "setgid", "shadow"], ["/usr/bin/crontab", "setgid", "crontab"], ["/usr/bin/passwd", "setuid", "root"], ["/usr/bin/su", "setuid", "root"], ["/usr/bin/sudo", "setuid", "root"], ["/usr/sbin/pppd", "setuid", "root"]]}, {"args": ["", "/usr/bin/ping cap_net_raw=ep\n/usr/bin/mtr-packet cap_net_raw=ep\n/usr/sbin/arping cap_net_raw=p\n/opt/app/bin/web cap_net_bind_service=ep\n/usr/local/bin/pyrun cap_setuid,cap_sys_admin=ep\n/opt/vm tools/qemu-bridge-helper cap_net_admin=ep\n", []], "expected": [["/opt/app/bin/web", "cap-unexpected", "cap_net_bind_service=ep"], ["/opt/vm tools/qemu-bridge-helper", "cap-unexpected", "cap_net_admin=ep"], ["/usr/bin/mtr-packet", "cap-unexpected", "cap_net_raw=ep"], ["/usr/bin/ping", "cap-unexpected", "cap_net_raw=ep"], ["/usr/local/bin/pyrun", "cap-dangerous", "cap_setuid,cap_sys_admin"], ["/usr/local/bin/pyrun", "cap-unexpected", "cap_setuid,cap_sys_admin=ep"], ["/usr/sbin/arping", "cap-unexpected", "cap_net_raw=p"]]}, {"args": ["", "", ["/usr/bin/passwd", "/usr/bin/sudo", "/usr/bin/su", "/usr/bin/chage", "/usr/bin/crontab", "/usr/sbin/pppd", "/usr/bin/mount", "/usr/lib/utempter/utempter", "/usr/bin/ping", "/usr/bin/mtr-packet", "/usr/sbin/arping", "/usr/local/bin/dacview"]], "expected": []}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 32, 'la32-audit-rules', 5, 'func', 'Проверка правил auditd', 'text - файл правил auditd (audit.rules): по одному правилу в строке; пустые строки и строки, начинающиеся с #, пропускайте; слова в строке разделены пробелами (кавычек нет). Нумерация строк с 1. Напишите функцию check_rules(text): верните отсортированный список [номер_строки, код] без повторов. Строка может дать несколько кодов. Грамматика и коды: -D без аргументов (иначе extra-argument). -b, -r, -f, -e - ровно один числовой аргумент (нет аргумента - missing-argument, лишние слова - extra-argument, не число или для -f и -e больше 2 - bad-value); строка ''-e 2'', после которой в файле есть ещё правила (непустые строки не комментарии), даёт immutable-not-last. -w ПУТЬ [-p ПРАВА] [-k КЛЮЧ] в любом порядке: путь без / в начале - relative-path; ПРАВА - только буквы r, w, x, a без повторов (иначе bad-perms); ключ длиннее 31 байта UTF-8 - key-too-long; опция без аргумента - missing-argument (разбор строки на этом заканчивается); другая опция - unknown-option; нет пути - missing-argument. -a (или -A) ДЕЙСТВИЕ,СПИСОК: ровно два слова через запятую, действие always или never, список task, exit, user, exclude, filesystem или io_uring, порядок любой - иначе bad-action (нет аргумента - missing-argument). После него опции в любом порядке: -S СПИСОК - имена через запятую без пробелов, каждое - слово all, число или имя из строчных букв, цифр и _ (иначе bad-syscall); -k КЛЮЧ - не длиннее 31 байта (иначе key-too-long); -F ПОЛЕ ОП ЗНАЧЕНИЕ одним словом, например auid>=1000, где операция - одна из !=, <=, >=, &=, =, <, >, & (нет такого вида - bad-field-syntax); поле из arch, auid, uid, euid, gid, egid, success, exit, path, dir, perm, key, pid, exe (иначе unknown-field); для поля perm - как ПРАВА выше (bad-perms), arch - только b32 или b64 (bad-arch), path и dir - начинаются с / (relative-path), success - 0 или 1 (bad-value), key - не длиннее 31 байта (key-too-long). Опция без аргумента - missing-argument (разбор строки заканчивается); другое слово - unknown-option. Дополнительные проверки правила -a: если список известен, он не exit и есть поле path, dir или perm - field-needs-exit; если есть -S и нет поля arch - no-arch. Любая другая первая опция строки - unknown-option.', 'def check_rules(text):
    pass
', 'Постройте словарь номер -> слова только для значимых строк. Для -a и -w разбирайте опции циклом с индексом i, который сдвигается на 2, если у опции есть аргумент; коды копите в множестве.', '{"func": "check_rules", "tests": [{"args": ["# audit rules for a KVM host\n-D\n-b 8192\n-f 1\n\n-w /etc/passwd -p wa -k identity\n-w /etc/libvirt/ -p wa -k libvirt_conf\n-a always,exit -F arch=b64 -S execve -k exec\n-a always,exit -F arch=b64 -F path=/usr/bin/sudo -F perm=x -F auid>=1000 -F auid!=4294967295 -k priv\n-a never,exit -F arch=b64 -S adjtimex,settimeofday\n-e 2\n"], "expected": []}, {"args": ["-D extra\n-b abc\n-f 3\n-w etc/shadow -p wa -k shadow\n-w /etc/shadow -p wax\n-w /etc/shadow -p ww -k dup\n-w /etc/hosts -k aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa\n-w /etc/hosts -x\n-w\n"], "expected": [[1, "extra-argument"], [2, "bad-value"], [3, "bad-value"], [4, "relative-path"], [6, "bad-perms"], [7, "key-too-long"], [8, "unknown-option"], [9, "missing-argument"]]}, {"args": ["-e 2\n-a always -S open\n-a exit,never -F arch=b64 -S 12345\n-a always,exit -S execve -k exec\n-a always,exit -F arch=b64 -S Open!\n-a always,exit -F arch=x86_64 -S openat\n-a always,exit -F arch=b64 -F pathh=/etc -S openat\n-a always,exit -F arch=b64 -F dir=etc -S openat\n-a always,exit -F arch=b64 -F success=2 -S openat\n-a always,task -F arch=b64 -F perm=x -S execve\n-a always,exit -F arch=b64 -F auid>=1000 -S execve -k\n-a always,exit -F arch=b64 -F exit\n-a always,exit,extra\n-a always,user -F arch=b64 -F dir=/tmp\n-w /etc/hosts -p r\n"], "expected": [[1, "immutable-not-last"], [2, "bad-action"], [2, "no-arch"], [4, "no-arch"], [5, "bad-syscall"], [6, "bad-arch"], [7, "unknown-field"], [8, "relative-path"], [9, "bad-value"], [10, "field-needs-exit"], [11, "missing-argument"], [12, "bad-field-syntax"], [13, "bad-action"], [14, "field-needs-exit"]]}, {"args": ["-e 2\n# the end\n\n"], "expected": []}, {"args": ["-e 2\n-D\n"], "expected": [[1, "immutable-not-last"]]}, {"args": ["-a always,exit -F arch=b64 -S execve -k exec\n-w /var/log/audit/ -p rwxa\n"], "expected": []}, {"args": [""], "expected": []}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 32, 'la32-incident-vm-down', 6, 'func', 'Экзамен 1: виртуальная машина остановилась', 'Инцидент: виртуальная машина не работает. Ответственный собрал словарь текстов a: ''vm'' - имя машины; ''virsh_list'' - вывод virsh list --all (столбцы Id, Name, State; состояние может состоять из двух слов, например ''shut off''); ''dmesg'' - журнал ядра; ''audit_log'' - фрагмент audit.log; ''qemu_log'' - журнал QEMU машины. Любого ключа, кроме ''vm'', может не быть (считайте его пустым текстом). Напишите функцию diagnose_vm(a): верните словарь {''cause'': ..., ''evidence'': [...], ''fix'': ...}. Порядок решения - первое подходящее правило. 1) В virsh_list машина vm в состоянии ''running'' - cause ''healthy'', fix ''none''. 2) В dmesg есть строка ''Out of memory: Killed process ПИД (ИМЯ)'' или ''Memory cgroup out of memory: Killed process ПИД (ИМЯ)'', где ИМЯ начинается с ''qemu'' (убийства других процессов не считаются). Если таких строк несколько, решает последняя. ''Memory cgroup out of memory'' - cause ''oom_cgroup'', fix ''raise-memory-limit''; ''Out of memory'' - cause ''oom_host'', fix ''reduce-overcommit''. 3) В audit_log есть запись avc: denied (между avc: и denied могут быть пробелы), у которой comm начинается с ''qemu'' или тип субъекта (третья часть scontext) начинается с ''svirt''. Если таких записей несколько, решает последняя. cause ''selinux''. Исправление по ней, первое подходящее: тип объекта (третья часть tcontext) равен nfs_t - ''set-boolean-virt-use-nfs''; тип объекта один из default_t, unlabeled_t, user_home_t, tmp_t, var_t, mnt_t, либо у scontext и tcontext есть пятая часть (категории вида c1,c2) и они различаются - ''relabel-image''; иначе ''review-denial''. 4) В dmesg есть строка с apparmor="DENIED" и profile="libvirt-..." (имя профиля начинается с libvirt-) - cause ''apparmor'', fix ''fix-profile''. 5) Иначе cause ''unknown'', fix ''collect-more''. Улики (evidence) - отсортированный список ключей: healthy - [''virsh_list'']; oom_host и oom_cgroup - [''dmesg'']; selinux - [''audit_log''] и, если в qemu_log есть ''Permission denied'', ещё ''qemu_log''; apparmor - [''dmesg''] и, при том же условии, ''qemu_log''; unknown - [].', 'def diagnose_vm(a):
    pass
', 'Идите по правилам сверху вниз и возвращайте результат первого сработавшего. Для AVC поля читайте re.findall, тип - split('':'')[2], категории - split('':'')[4].', '{"func": "diagnose_vm", "tests": [{"args": [{"vm": "db01", "virsh_list": " Id   Name    State\n-------------------------\n 3    db01    running\n 7    web01   running\n", "dmesg": "[ 8120.100000] eth0: link up\n[ 8123.455000] qemu-system-x86 invoked oom-killer: gfp_mask=0x140cca(GFP_HIGHUSER_MOVABLE|__GFP_COMP), order=0, oom_score_adj=0\n[ 8123.456999] oom-kill:constraint=CONSTRAINT_NONE,nodemask=(null),cpuset=/,mems_allowed=0,global_oom,task_memcg=/machine.slice/machine-qemu-3-web01.scope,task=qemu-system-x86,pid=7771,uid=107\n[ 8123.457000] Out of memory: Killed process 7771 (qemu-system-x86) total-vm:9123456kB, anon-rss:7912340kB, file-rss:1204kB, shmem-rss:16kB, UID:107 pgtables:16120kB oom_score_adj:0\n", "audit_log": "type=AVC msg=audit(1699000001.100:7001): avc:  denied  { read } for  pid=812 comm=\"qemu-kvm\" name=\"web01.qcow2\" dev=\"0:45\" ino=393 scontext=system_u:system_r:svirt_t:s0:c1,c2 tcontext=system_u:object_r:nfs_t:s0 tclass=file permissive=0\n"}], "expected": {"cause": "healthy", "evidence": ["virsh_list"], "fix": "none"}}, {"args": [{"vm": "web01", "virsh_list": " Id   Name    State\n-------------------------\n 3    db01    running\n -    web01   shut off\n", "dmesg": "[ 8120.100000] eth0: link up\n[ 8123.455000] qemu-system-x86 invoked oom-killer: gfp_mask=0x140cca(GFP_HIGHUSER_MOVABLE|__GFP_COMP), order=0, oom_score_adj=0\n[ 8123.456999] oom-kill:constraint=CONSTRAINT_NONE,nodemask=(null),cpuset=/,mems_allowed=0,global_oom,task_memcg=/machine.slice/machine-qemu-3-web01.scope,task=qemu-system-x86,pid=7771,uid=107\n[ 8123.457000] Out of memory: Killed process 7771 (qemu-system-x86) total-vm:9123456kB, anon-rss:7912340kB, file-rss:1204kB, shmem-rss:16kB, UID:107 pgtables:16120kB oom_score_adj:0\n", "audit_log": "type=AVC msg=audit(1699000001.100:7001): avc:  denied  { read } for  pid=812 comm=\"qemu-kvm\" name=\"web01.qcow2\" dev=\"0:45\" ino=393 scontext=system_u:system_r:svirt_t:s0:c1,c2 tcontext=system_u:object_r:nfs_t:s0 tclass=file permissive=0\n", "qemu_log": "2026-11-03T10:02:11.123456Z qemu-system-x86_64: -blockdev {\"driver\":\"file\",\"filename\":\"/srv/images/web01.qcow2\"}: Could not open ''/srv/images/web01.qcow2'': Permission denied\n"}], "expected": {"cause": "oom_host", "evidence": ["dmesg"], "fix": "reduce-overcommit"}}, {"args": [{"vm": "web01", "virsh_list": " Id   Name    State\n-------------------------\n -    web01   crashed\n", "dmesg": "[ 7000.000000] java invoked oom-killer: gfp_mask=0x140cca(GFP_HIGHUSER_MOVABLE|__GFP_COMP), order=0, oom_score_adj=0\n[ 7000.000100] Out of memory: Killed process 4321 (java) total-vm:8123456kB, anon-rss:3912340kB, file-rss:1204kB, shmem-rss:16kB, UID:1000 pgtables:8120kB oom_score_adj:0\n[ 9001.200000] qemu-system-x86 invoked oom-killer: gfp_mask=0x100cca(GFP_HIGHUSER_MOVABLE), order=0, oom_score_adj=0\n[ 9001.200100] oom-kill:constraint=CONSTRAINT_MEMCG,nodemask=(null),cpuset=/,mems_allowed=0,oom_memcg=/machine.slice/machine-qemu-3-web01.scope,task_memcg=/machine.slice/machine-qemu-3-web01.scope,task=qemu-system-x86,pid=7771,uid=107\n[ 9001.200200] Memory cgroup out of memory: Killed process 7771 (qemu-system-x86) total-vm:5120000kB, anon-rss:4194304kB, file-rss:9000kB, shmem-rss:1000kB, UID:107 pgtables:9000kB oom_score_adj:-100\n", "qemu_log": "2026-11-03 10:02:11.000+0000: shutting down, reason=crashed\n"}], "expected": {"cause": "oom_cgroup", "evidence": ["dmesg"], "fix": "raise-memory-limit"}}, {"args": [{"vm": "web01", "virsh_list": " Id   Name    State\n-------------------------\n 3    db01    running\n -    web01   shut off\n", "dmesg": "[ 9001.200000] qemu-system-x86 invoked oom-killer: gfp_mask=0x100cca(GFP_HIGHUSER_MOVABLE), order=0, oom_score_adj=0\n[ 9001.200100] oom-kill:constraint=CONSTRAINT_MEMCG,nodemask=(null),cpuset=/,mems_allowed=0,oom_memcg=/machine.slice/machine-qemu-3-web01.scope,task_memcg=/machine.slice/machine-qemu-3-web01.scope,task=qemu-system-x86,pid=7771,uid=107\n[ 9001.200200] Memory cgroup out of memory: Killed process 7771 (qemu-system-x86) total-vm:5120000kB, anon-rss:4194304kB, file-rss:9000kB, shmem-rss:1000kB, UID:107 pgtables:9000kB oom_score_adj:-100\n[ 8120.100000] eth0: link up\n[ 8123.455000] qemu-system-x86 invoked oom-killer: gfp_mask=0x140cca(GFP_HIGHUSER_MOVABLE|__GFP_COMP), order=0, oom_score_adj=0\n[ 8123.456999] oom-kill:constraint=CONSTRAINT_NONE,nodemask=(null),cpuset=/,mems_allowed=0,global_oom,task_memcg=/machine.slice/machine-qemu-3-web01.scope,task=qemu-system-x86,pid=7771,uid=107\n[ 8123.457000] Out of memory: Killed process 7771 (qemu-system-x86) total-vm:9123456kB, anon-rss:7912340kB, file-rss:1204kB, shmem-rss:16kB, UID:107 pgtables:16120kB oom_score_adj:0\n"}], "expected": {"cause": "oom_host", "evidence": ["dmesg"], "fix": "reduce-overcommit"}}, {"args": [{"vm": "web01", "virsh_list": " Id   Name    State\n-------------------------\n 3    db01    running\n -    web01   shut off\n", "dmesg": "", "audit_log": "type=AVC msg=audit(1699000001.100:7001): avc:  denied  { read } for  pid=812 comm=\"qemu-kvm\" name=\"web01.qcow2\" dev=\"0:45\" ino=393 scontext=system_u:system_r:svirt_t:s0:c1,c2 tcontext=system_u:object_r:nfs_t:s0 tclass=file permissive=0\n", "qemu_log": "2026-11-03T10:02:11.123456Z qemu-system-x86_64: -blockdev {\"driver\":\"file\",\"filename\":\"/srv/images/web01.qcow2\"}: Could not open ''/srv/images/web01.qcow2'': Permission denied\n"}], "expected": {"cause": "selinux", "evidence": ["audit_log", "qemu_log"], "fix": "set-boolean-virt-use-nfs"}}, {"args": [{"vm": "web01", "virsh_list": " Id   Name    State\n-------------------------\n 3    db01    running\n -    web01   shut off\n", "audit_log": "type=AVC msg=audit(1699000002.100:7002): avc:  denied  { read } for  pid=812 comm=\"qemu-kvm\" name=\"web01.qcow2\" dev=\"0:45\" ino=393 scontext=system_u:system_r:svirt_t:s0:c1,c2 tcontext=unconfined_u:object_r:default_t:s0 tclass=file permissive=0\n", "qemu_log": "2026-11-03 10:02:11.000+0000: shutting down, reason=crashed\n"}], "expected": {"cause": "selinux", "evidence": ["audit_log"], "fix": "relabel-image"}}, {"args": [{"vm": "web01", "virsh_list": " Id   Name    State\n-------------------------\n 3    db01    running\n -    web01   shut off\n", "audit_log": "type=AVC msg=audit(1699000005.100:7005): avc:  denied  { read } for  pid=812 comm=\"httpd\" name=\"web01.qcow2\" dev=\"0:45\" ino=393 scontext=system_u:system_r:httpd_t:s0 tcontext=unconfined_u:object_r:user_home_t:s0 tclass=file permissive=0\ntype=AVC msg=audit(1699000003.100:7003): avc:  denied  { read } for  pid=812 comm=\"qemu-kvm\" name=\"web01.qcow2\" dev=\"0:45\" ino=393 scontext=system_u:system_r:svirt_t:s0:c1,c2 tcontext=system_u:object_r:svirt_image_t:s0:c7,c8 tclass=file permissive=0\n"}], "expected": {"cause": "selinux", "evidence": ["audit_log"], "fix": "relabel-image"}}, {"args": [{"vm": "web01", "virsh_list": " Id   Name    State\n-------------------------\n 3    db01    running\n -    web01   shut off\n", "audit_log": "type=AVC msg=audit(1699000004.100:7004): avc:  denied  { read } for  pid=812 comm=\"qemu-kvm\" name=\"web01.qcow2\" dev=\"0:45\" ino=393 scontext=system_u:system_r:svirt_t:s0:c1,c2 tcontext=system_u:object_r:etc_t:s0 tclass=file permissive=0\n"}], "expected": {"cause": "selinux", "evidence": ["audit_log"], "fix": "review-denial"}}, {"args": [{"vm": "web01", "virsh_list": " Id   Name    State\n-------------------------\n 3    db01    running\n -    web01   shut off\n", "audit_log": "type=AVC msg=audit(1699000006.100:7006): avc:  denied  { getattr } for  pid=812 comm=\"qemu-kvm\" name=\"web01.qcow2\" dev=\"0:45\" ino=393 scontext=system_u:system_r:svirt_t:s0:c1,c2 tcontext=system_u:object_r:svirt_image_t:s0:c1,c2 tclass=file permissive=0\n"}], "expected": {"cause": "selinux", "evidence": ["audit_log"], "fix": "review-denial"}}, {"args": [{"vm": "web01", "virsh_list": " Id   Name    State\n-------------------------\n 3    db01    running\n -    web01   shut off\n", "audit_log": "type=AVC msg=audit(1699000001.100:7001): avc:  denied  { read } for  pid=812 comm=\"qemu-kvm\" name=\"web01.qcow2\" dev=\"0:45\" ino=393 scontext=system_u:system_r:svirt_t:s0:c1,c2 tcontext=system_u:object_r:nfs_t:s0 tclass=file permissive=0\ntype=AVC msg=audit(1699000002.100:7002): avc:  denied  { read } for  pid=812 comm=\"qemu-kvm\" name=\"web01.qcow2\" dev=\"0:45\" ino=393 scontext=system_u:system_r:svirt_t:s0:c1,c2 tcontext=unconfined_u:object_r:default_t:s0 tclass=file permissive=0\n"}], "expected": {"cause": "selinux", "evidence": ["audit_log"], "fix": "relabel-image"}}, {"args": [{"vm": "web01", "virsh_list": " Id   Name    State\n-------------------------\n 3    db01    running\n -    web01   shut off\n", "dmesg": "[ 9500.000000] audit: type=1400 audit(1699000001.100:301): apparmor=\"DENIED\" operation=\"open\" profile=\"libvirt-4a1b2c3d-1111-2222-3333-444455556666\" name=\"/srv/images/web01.qcow2\" pid=2210 comm=\"qemu-system-x86\" requested_mask=\"wr\" denied_mask=\"wr\" fsuid=64055 ouid=0\n", "qemu_log": "2026-11-03T10:02:11.123456Z qemu-system-x86_64: -blockdev {\"driver\":\"file\",\"filename\":\"/srv/images/web01.qcow2\"}: Could not open ''/srv/images/web01.qcow2'': Permission denied\n"}], "expected": {"cause": "apparmor", "evidence": ["dmesg", "qemu_log"], "fix": "fix-profile"}}, {"args": [{"vm": "web01", "virsh_list": " Id   Name    State\n-------------------------\n 3    db01    running\n -    web01   shut off\n", "dmesg": "[ 9500.000000] audit: type=1400 audit(1699000001.100:301): apparmor=\"DENIED\" operation=\"open\" profile=\"/usr/sbin/cups-browsed\" name=\"/var/lib/libvirt/dnsmasq/\" pid=1128 comm=\"cups-browsed\" requested_mask=\"r\" denied_mask=\"r\" fsuid=0 ouid=0\n[ 9500.100000] audit: type=1400 audit(1699000001.200:302): apparmor=\"ALLOWED\" operation=\"open\" profile=\"libvirt-4a1b2c3d-1111-2222-3333-444455556666\" name=\"/srv/images/web01.qcow2\" pid=2210 comm=\"qemu-system-x86\" requested_mask=\"r\" denied_mask=\"r\" fsuid=64055 ouid=0\n[ 7000.000000] java invoked oom-killer: gfp_mask=0x140cca(GFP_HIGHUSER_MOVABLE|__GFP_COMP), order=0, oom_score_adj=0\n[ 7000.000100] Out of memory: Killed process 4321 (java) total-vm:8123456kB, anon-rss:3912340kB, file-rss:1204kB, shmem-rss:16kB, UID:1000 pgtables:8120kB oom_score_adj:0\n", "audit_log": "type=AVC msg=audit(1699000005.100:7005): avc:  denied  { read } for  pid=812 comm=\"httpd\" name=\"web01.qcow2\" dev=\"0:45\" ino=393 scontext=system_u:system_r:httpd_t:s0 tcontext=unconfined_u:object_r:user_home_t:s0 tclass=file permissive=0\n", "qemu_log": "2026-11-03 10:02:11.000+0000: shutting down, reason=crashed\n"}], "expected": {"cause": "unknown", "evidence": [], "fix": "collect-more"}}, {"args": [{"vm": "web01"}], "expected": {"cause": "unknown", "evidence": [], "fix": "collect-more"}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 32, 'la32-incident-enospc', 7, 'func', 'Экзамен 2: «No space left on device»', 'Инцидент: запись на диск закончилась ошибкой ''No space left on device'', хотя место, возможно, есть. Словарь текстов a: ''journal'' - строки журнала; ''df'' - вывод df -k (столбцы Filesystem 1K-blocks Used Available Use% Mounted on; точка монтирования - всё после 5-го столбца, в ней могут быть пробелы); ''df_i'' - вывод df -i (Filesystem Inodes IUsed IFree IUse% Mounted on; в IUse% может стоять ''-''); ''lsof_deleted'' - вывод lsof +L1 (столбцы COMMAND PID USER FD TYPE DEVICE SIZE/OFF NLINK NODE NAME; имя файла - всё после 9-го столбца и оканчивается словом ''(deleted)''); ''lvs'' - вывод lvs --noheadings --separator '';'' -o lv_name,vg_name,lv_attr,data_percent,metadata_percent (поля, не относящиеся к тонким томам, пустые). Ключи ''lsof_deleted'' и ''lvs'' могут отсутствовать. Напишите функцию diagnose_enospc(a): верните {''cause'': ..., ''evidence'': [...], ''fix'': ...}. Порядок решения. 0) Найдите в journal первую строку с ''No space left on device'', содержащую путь: первую подстроку, которая начинается с ''/'' и тянется до пробела, кавычки ('' или "), двоеточия, запятой или точки с запятой. Если такой строки нет - cause ''not_enospc'', fix ''look-elsewhere'', evidence [''journal'']. 1) Файловая система пути - строка df с самой длинной точкой монтирования, которая равна пути или является его каталогом-префиксом по границе имени (''/'' подходит всегда; ''/var/lib/images'' не префикс ''/var/lib/images2/a''). Если её Use% не меньше 95: сложите размеры (SIZE/OFF) удалённых файлов из lsof_deleted, чьи пути лежат на этой же файловой системе (самая длинная точка монтирования та же); один и тот же файл (одинаковые DEVICE и NODE) считайте один раз; строки без размера-числа пропускайте. Если сумма в байтах не меньше 10% размера файловой системы (1K-blocks * 1024) - cause ''deleted_open'', fix ''restart-holder-process'', evidence [''df'', ''journal'', ''lsof_deleted'']; иначе cause ''disk_full'', fix ''free-or-extend'', evidence [''df'', ''journal'']. 2) Иначе, если IUse% этой точки монтирования в df_i не меньше 95 - cause ''inodes_exhausted'', fix ''remove-small-files'', evidence [''df_i'', ''journal'']. 3) Иначе, если в lvs есть тонкий пул (первая буква lv_attr равна ''t'') с data_percent или metadata_percent не меньше 95 - cause ''thin_pool_full'', fix ''extend-thin-pool'', evidence [''journal'', ''lvs'']. 4) Иначе cause ''unexplained'', fix ''check-quota-and-reserved'', evidence [''df'', ''df_i'', ''journal''].', 'def diagnose_enospc(a):
    pass
', 'Сначала путь из журнала, потом самая длинная точка монтирования с проверкой границы имени. Для lsof: t[5] - DEVICE, t[6] - размер, t[8] - NODE, t[9:-1] - имя.', '{"func": "diagnose_enospc", "tests": [{"args": [{"journal": "Nov 03 10:02:11 kvm01 backup.sh[400]: rsync: [receiver] write failed on \"/var/lib/libvirt/images/web01.qcow2\": No space left on device (28)\nNov 03 10:02:11 kvm01 backup.sh[400]: rsync error: error in file IO (code 11) at receiver.c(378) [receiver=3.2.7]\n", "df": "Filesystem                    1K-blocks      Used Available Use% Mounted on\n/dev/mapper/vg0-root           51475068  12345678  36488522  26% /\n/dev/mapper/vg0-images        209612800 209612800         0 100% /var/lib/libvirt/images\n/dev/sda1                        524272      6120    518152   2% /boot/efi\ntmpfs                           8010232         0   8010232   0% /dev/shm\n", "df_i": "Filesystem                     Inodes   IUsed    IFree IUse% Mounted on\n/dev/mapper/vg0-root          3276800  201433  3075367    7% /\n/dev/mapper/vg0-images       13107200  120113 12987087    1% /var/lib/libvirt/images\n/dev/sda1                           0       0        0     - /boot/efi\ntmpfs                         2002558       1  2002557    1% /dev/shm\n", "lsof_deleted": "COMMAND   PID USER   FD   TYPE DEVICE   SIZE/OFF NLINK    NODE NAME\nlogrotate 900 root    3w   REG  253,0    1048576     0     456 /var/log/app.log (deleted)\nsystemd     1 root   12r   REG  253,0       4096     0     789 /tmp/.X11-unix/lock (deleted)\n"}], "expected": {"cause": "disk_full", "evidence": ["df", "journal"], "fix": "free-or-extend"}}, {"args": [{"journal": "Nov 03 10:02:11 kvm01 backup.sh[400]: rsync: [receiver] write failed on \"/var/lib/libvirt/images/web01.qcow2\": No space left on device (28)\nNov 03 10:02:11 kvm01 backup.sh[400]: rsync error: error in file IO (code 11) at receiver.c(378) [receiver=3.2.7]\n", "df": "Filesystem                    1K-blocks      Used Available Use% Mounted on\n/