7    7% /\n/dev/mapper/vg0-images       13107200 13107200        0  100% /var/lib/libvirt/images\n"}], "expected": {"cause": "unexplained", "evidence": ["df", "df_i", "journal"], "fix": "check-quota-and-reserved"}}, {"args": [{"journal": "Nov 03 10:06:00 kvm01 tar[77]: /var/lib/libvirt/images2/old.tar: Cannot write: No space left on device\n", "df": "Filesystem                    1K-blocks      Used Available Use% Mounted on\n/dev/mapper/vg0-root           51475068  12345678  36488522  26% /\n/dev/mapper/vg0-images        209612800 209612800         0 100% /var/lib/libvirt/images\n/dev/sda1                        524272      6120    518152   2% /boot/efi\ntmpfs                           8010232         0   8010232   0% /dev/shm\n", "df_i": "Filesystem                     Inodes   IUsed    IFree IUse% Mounted on\n/dev/mapper/vg0-root          3276800  201433  3075367    7% /\n/dev/mapper/vg0-images       13107200  120113 12987087    1% /var/lib/libvirt/images\n/dev/sda1                           0       0        0     - /boot/efi\ntmpfs                         2002558       1  2002557    1% /dev/shm\n", "lvs": "  root;vg0;-wi-ao----;;\n  pool0;vg0;twi-aotz--;99.10;18.40\n  vm1;vg0;Vwi-aotz--;96.00;\n"}], "expected": {"cause": "thin_pool_full", "evidence": ["journal", "lvs"], "fix": "extend-thin-pool"}}, {"args": [{"journal": "Nov 03 10:07:00 kvm01 qemu-img[1]: qemu-img: Could not open ''/var/lib/libvirt/images/web01.qcow2'': Permission denied\n", "df": "Filesystem                    1K-blocks      Used Available Use% Mounted on\n/dev/mapper/vg0-root           51475068  12345678  36488522  26% /\n/dev/mapper/vg0-images        209612800 209612800         0 100% /var/lib/libvirt/images\n/dev/sda1                        524272      6120    518152   2% /boot/efi\ntmpfs                           8010232         0   8010232   0% /dev/shm\n", "df_i": "Filesystem                     Inodes   IUsed    IFree IUse% Mounted on\n/dev/mapper/vg0-root          3276800  201433  3075367    7% /\n/dev/mapper/vg0-images       13107200  120113 12987087    1% /var/lib/libvirt/images\n/dev/sda1                           0       0        0     - /boot/efi\ntmpfs                         2002558       1  2002557    1% /dev/shm\n"}], "expected": {"cause": "not_enospc", "evidence": ["journal"], "fix": "look-elsewhere"}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 32, 'la32-incident-lockout', 8, 'func', 'Экзамен 3: хост пропал из сети', 'Инцидент: после изменения конфигурации администратор не может подключиться к хосту по SSH. Словарь текстов a (все значения - строки): ''iface'' - имя управляющего интерфейса; ''client'' - IPv4-адрес администратора; ''port'' - порт SSH (число строкой); ''ip_addr'' - вывод ip addr (заголовок интерфейса ''2: eth0: <ФЛАГИ> mtu ... master br0 state UP ...'', слово master есть только у порта моста; ниже строки ''    inet АДРЕС/ДЛИНА ...''; строки inet6 игнорируйте); ''ip_route'' - вывод ip route; ''nft_ruleset'' - вывод nft list ruleset; ''ss_listen'' - вывод ss -tln. Напишите функцию diagnose_lockout(a): верните {''cause'': ..., ''evidence'': [...], ''fix'': ...}. Порядок решения - первое подходящее правило, от нижних слоёв к верхним. 1) Интерфейса iface нет в ip_addr - cause ''iface_missing'', fix ''restore-interface-config'', evidence [''ip_addr'']. 2) Интерфейс (или мост, чей порт он, если есть master и блок моста есть в выводе) в состоянии state DOWN или с флагом NO-CARRIER - ''link_down'', ''bring-link-up'', [''ip_addr'']. 3) У интерфейса есть master, на самом интерфейсе есть адрес inet, а у моста адреса нет (или блока моста нет) - ''address_on_port'', ''move-address-to-bridge'', [''ip_addr'']. 4) Держатель адреса (мост, если у интерфейса есть master и блок моста есть, иначе сам интерфейс) не имеет ни одной строки inet - ''no_address'', ''assign-address'', [''ip_addr'']. 5) Маршруты. Подключённые сети - строки ip_route, не начинающиеся с default, со словами ''scope link'' и без слова linkdown; их первое слово - сеть. Если адрес client лежит в подключённой сети, маршрутов достаточно. Иначе: нет строки default - ''no_default_route'', ''add-default-route'', [''ip_route'']; у первой строки default есть ''via ШЛЮЗ'', но шлюз не лежит ни в одной подключённой сети - ''gateway_unreachable'', ''fix-gateway'', [''ip_route'']. 6) Файрвол. Рассматривайте базовые цепочки с ''hook input'' в таблицах семейств ip и inet; каждая решает сама, её пакет считается плохим, если вердикт drop или reject. Пакет - новое TCP-соединение с client на port. Правила цепочки идут сверху вниз; первое подошедшее решает, если подходящих нет - решает policy (по умолчанию accept). Правило без accept, drop или reject пропускайте (оно не подходит). Правило с icmp или udp, а также с iif или iifname "lo" не подходит. ''counter ...'', ''log ...'' и ''comment "..."'' игнорируйте. ''ct state СПИСОК'' подходит, если в списке есть new. ''ip saddr [!=] ЗНАЧЕНИЕ'' подходит, если адрес client входит (для !=: не входит) в значение: адрес, сеть, диапазон ''а-б'' или множество в фигурных скобках через запятую из них. ''tcp dport [!=] ЗНАЧЕНИЕ'' аналогично для port (число, диапазон, множество); без условия tcp dport порт не ограничен. Вердикт правила - его слово accept, drop или reject. Если хоть одна такая цепочка отбрасывает пакет - ''firewall'', ''allow-ssh-rule'', [''nft_ruleset'']. 7) В ss_listen нет строки LISTEN с локальным портом port на неloopback-адресе (адреса, начинающиеся с 127. и [::1], не считаются; * и [::] считаются) - ''sshd_not_listening'', ''fix-sshd-listen'', [''ss_listen'']. 8) Иначе ''unknown'', ''collect-more'', [].', 'def diagnose_lockout(a):
    pass
', 'Разберите ip_addr в словарь интерфейс -> {master, state, flags, inet}. Для файрвола достаточно построчного конечного автомата: table, chain, type...hook, правила; затем проверка условий регулярными выражениями.', '{"func": "diagnose_lockout", "tests": [{"args": [{"iface": "eth0", "client": "198.51.100.7", "port": "22", "ip_addr": "1: lo: <LOOPBACK,UP,LOWER_UP> mtu 65536 qdisc noqueue state UNKNOWN group default qlen 1000\n    link/loopback 00:00:00:00:00:00 brd 00:00:00:00:00:00\n    inet 127.0.0.1/8 scope host lo\n       valid_lft forever preferred_lft forever\n2: ens3: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 qdisc fq_codel state UP group default qlen 1000\n    link/ether 52:54:00:aa:bb:02 brd ff:ff:ff:ff:ff:ff\n    inet 192.0.2.10/24 brd 192.0.2.255 scope global ens3\n       valid_lft forever preferred_lft forever\n    inet6 fe80::5054:ff:feaa:bb02/64 scope link \n       valid_lft forever preferred_lft forever\n", "ip_route": "default via 192.0.2.1 dev eth0 proto static\n192.0.2.0/24 dev eth0 proto kernel scope link src 192.0.2.10\n", "nft_ruleset": "table inet filter {\n\tchain input {\n\t\ttype filter hook input priority filter; policy drop;\n\t\tct state established,related accept\n\t\tiif \"lo\" accept\n\t\ttcp dport 22 accept\n\t\tip protocol icmp accept\n\t}\n}\n", "ss_listen": "State   Recv-Q  Send-Q   Local Address:Port    Peer Address:Port Process\nLISTEN  0       128            0.0.0.0:22           0.0.0.0:*     users:((\"sshd\",pid=801,fd=3))\nLISTEN  0       128               [::]:22              [::]:*     users:((\"sshd\",pid=801,fd=4))\nLISTEN  0       511          127.0.0.1:6379          0.0.0.0:*     users:((\"redis-server\",pid=1020,fd=6))\n"}], "expected": {"cause": "iface_missing", "evidence": ["ip_addr"], "fix": "restore-interface-config"}}, {"args": [{"iface": "eth0", "client": "198.51.100.7", "port": "22", "ip_addr": "1: lo: <LOOPBACK,UP,LOWER_UP> mtu 65536 qdisc noqueue state UNKNOWN group default qlen 1000\n    link/loopback 00:00:0