INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 32, 'la32-incident-storage-freeze', 9, 'func', 'Экзамен 4: хост и виртуальные машины замерли', 'Инцидент: виртуальные машины на хосте зависли, ввод-вывод стоит. Словарь текстов a (любого ключа может не быть - считайте его пустым): ''multipath_ll'' - вывод multipath -ll; ''dmesg'' - журнал ядра; ''vmstat'' - вывод vmstat 1 N. Напишите функцию diagnose_freeze(a): верните {''cause'': ..., ''evidence'': [...], ''fix'': ...}. Порядок решения - первое подходящее правило (сначала ошибки, потом нагрузка). 1) multipath_ll. Карта начинается строкой вида ''имя (WWID) dm-N ...'' либо ''WWID dm-N ...''; следующая строка ''size=... features=...'' показывает, есть ли в features слово queue_if_no_path. Путь - строка со словами ''H:C:T:L устройство мажор:минор СОСТОЯНИЕ_DM СОСТОЯНИЕ_ПУТИ СОСТОЯНИЕ_УСТРОЙСТВА'', например ''5:0:0:1 sdb 8:16 failed faulty offline''. Карта ''упала'', если у неё есть хотя бы один путь и ни у одного пути СОСТОЯНИЕ_DM не равно active. Если упала хотя бы одна карта с queue_if_no_path - cause ''multipath_hang'', fix ''restore-paths-limit-queueing''; иначе, если упала какая-то карта - cause ''multipath_failed'', fix ''restore-san-paths''. Evidence в обоих случаях [''multipath_ll'']. 2) dmesg, строки ''nfs: server ИМЯ not responding, still trying'' и ''nfs: server ИМЯ OK''. Для каждого сервера важна последняя из таких строк; если хотя бы у одного сервера она ''not responding'' - cause ''nfs_hung'', fix ''check-nfs-server-and-network'', evidence [''dmesg'']. 3) dmesg, строки с ''I/O error, dev УСТРОЙСТВО,''. Если для какого-то устройства таких строк не меньше трёх - cause ''disk_error'', fix ''replace-disk-check-raid'', evidence [''dmesg'']. 4) vmstat. Заголовок - строка, где есть слова wa и id (имена столбцов: r b swpd free buff cache si so bi bo in cs us sy id wa st, у новых версий в конце может быть ещё gu); данные - строки из чисел с тем же числом слов, что в заголовке. Берите последнюю строку данных, столбцы - по именам. Если st не меньше 20 - cause ''cpu_steal'', fix ''migrate-vms-or-reduce-overcommit'', evidence [''vmstat'']; иначе, если wa не меньше 30 - cause ''iowait'', fix ''run-iostat-find-device'', evidence [''vmstat'']. 5) Иначе cause ''no_fault_found'', fix ''collect-more'', evidence [].', 'def diagnose_freeze(a):
    pass
', 'Карты multipath делите по строкам с ''dm-N''; для путей хватит re.search(r''\d+:\d+:\d+:\d+\s+\S+\s+\d+:\d+\s+(\S+)''). Для vmstat zip(заголовок, значения).', '{"func": "diagnose_freeze", "tests": [{"args": [{"multipath_ll": "mpatha (36001405aa11bb22cc33dd44ee55ff660) dm-2 LIO-ORG,disk1\nsize=100G features=''1 queue_if_no_path'' hwhandler=''1 alua'' wp=rw\n|-+- policy=''service-time 0'' prio=0 status=enabled\n| |- 5:0:0:1 sdb 8:16 failed faulty offline\n| `- 6:0:0:1 sdd 8:48 failed faulty offline\n`-+- policy=''service-time 0'' prio=0 status=enabled\n  `- 7:0:0:1 sdc 8:32 failed faulty offline\n", "dmesg": "[ 5000.100000] nfs: server nfs01 not responding, still trying\n[ 5000.200000] nfs: server nfs02 not responding, still trying\n[ 5100.300000] nfs: server nfs02 OK\n", "vmstat": "procs -----------memory---------- ---swap-- -----io---- -system-- ------cpu-----\n r  b   swpd   free   buff  cache   si   so    bi    bo   in   cs us sy id wa st\n 9  0      0 123456  23456 987654    0    0     5    20 9100 8200 55 12 10  1 22\n 8  0      0 123400  23456 987654    0    0     0    16 9200 8300 51 14  8  1 26\n"}], "expected": {"cause": "multipath_hang", "evidence": ["multipath_ll"], "fix": "restore-paths-limit-queueing"}}, {"args": [{"multipath_ll": "36001405cc77dd88ee99ff00aa11bb220 dm-3 NETAPP,LUN C-Mode\nsize=500G features=''0'' hwhandler=''1 alua'' wp=rw\n|-+- policy=''service-time 0'' prio=0 status=enabled\n| |- 5:0:1:2 sde 8:64 failed faulty offline\n| `- 6:0:1:2 sdf 8:80 failed faulty offline\n", "dmesg": "[ 6000.100000] blk_update_request: I/O error, dev sdb, sector 2048 op 0x0:(READ) flags 0x0 phys_seg 1 prio class 0\n[ 6000.200000] blk_update_request: I/O error, dev sdb, sector 4096 op 0x0:(READ) flags 0x0 phys_seg 1 prio class 0\n[ 6000.300000] Buffer I/O error on dev sdb1, logical block 512, async page read\n[ 6000.400000] blk_update_request: I/O error, dev sdb, sector 8192 op 0x1:(WRITE) flags 0x800 phys_seg 1 prio class 0\n"}], "expected": {"cause": "multipath_failed", "evidence": ["multipath_ll"], "fix": "restore-san-paths"}}, {"args": [{"multipath_ll": "mpatha (36001405aa11bb22cc33dd44ee55ff660) dm-2 LIO-ORG,disk1\nsize=100G features=''1 queue_if_no_path'' hwhandler=''1 alua'' wp=rw\n|-+- policy=''service-time 0'' prio=50 status=active\n| |- 5:0:0:1 sdb 8:16 failed faulty offline\n| `- 6:0:0:1 sdd 8:48 active ready running\n`-+- policy=''service-time 0'' prio=10 status=enabled\n  `- 7:0:0:1 sdc 8:32 failed faulty offline\n", "vmstat": "procs -----------memory---------- ---swap-- -----io---- -system-- ------cpu-----\n r  b   swpd   free   buff  cache   si   so    bi    bo   in   cs us sy id wa st\n 3  0      0 123456  23456 987654    0    0     5    20  100  200  5  2 91  1  1\n 2  0      0 123450  23456 987654    0    0     0    16  110  210  4  2 93  0  1\n"}], "expected": {"cause": "no_fault_found", "evidence": [], "fix": "collect-more"}}, {"args": [{"multipath_ll": "mpatha (36001405aa11bb22cc33dd44ee55ff660) dm-2 LIO-ORG,disk1\nsize=100G features=''0'' hwhandler=''1 alua'' wp=rw\n`-+- policy=''service-time 0'' prio=50 status=active\n  |- 5:0:0:1 sdb 8:16 active ready running\n  `- 6:0:0:1 sdd 8:48 active ready running\nmpathb (3600a09803830476f6a2b4f6e7a6d4b31) dm-4 NETAPP,LUN C-Mode\nsize=1.0T features=''1 queue_if_no_path'' hwhandler=''1 alua'' wp=rw\n`-+- policy=''service-time 0'' prio=1 status=enabled\n  `- 3:0:0:0 sdg 8:96 failed faulty offline\n", "dmesg": ""}], "expected": {"cause": "multipath_hang", "evidence": ["multipath_ll"], "fix": "restore-paths-limit-queueing"}}, {"args": [{"multipath_ll": "mpatha (36001405aa11bb22cc33dd44ee55ff660) dm-2 LIO-ORG,disk1\nsize=100G features=''1 queue_if_no_path'' hwhandler=''1 alua'' wp=rw\n|-+- policy=''service-time 0'' prio=50 status=active\n| |- 5:0:0:1 sdb 8:16 failed faulty offline\n| `- 6:0:0:1 sdd 8:48 active ready running\n`-+- policy=''service-time 0'' prio=10 status=enabled\n  `- 7:0:0:1 sdc 8:32 failed faulty offline\n", "dmesg": "[ 5000.100000] nfs: server nfs01 not responding, still trying\n[ 5000.200000] nfs: server nfs02 not responding, still trying\n[ 5100.300000] nfs: server nfs02 OK\n", "vmstat": "procs -----------memory---------- ---swap-- -----io---- -system-- -------cpu-------\n r  b   swpd   free   buff  cache   si   so    bi    bo   in   cs us sy id wa st gu\n 1  6      0  98000  23456 987654    0    0 52000  1200 1100 2200  4  3 38 55  0  0\n 0  7      0  97000  23456 987654    0    0 49000  1300 1000 2100  3  2 36 59  0  0\n"}], "expected": {"cause": "nfs_hung", "evidence": ["dmesg"], "fix": "check-nfs-server-and-network"}}, {"args": [{"multipath_ll": "", "dmesg": "[ 5000.100000] nfs: server nfs01 not responding, still trying\n[ 5060.200000] nfs: server nfs01 OK\n[ 6000.100000] blk_update_request: I/O error, dev sdc, sector 2048 op 0x0:(READ) flags 0x0 phys_seg 1 prio class 0\n[ 6000.200000] blk_update_request: I/O error, dev sdd, sector 4096 op 0x0:(READ) flags 0x0 phys_seg 1 prio class 0\n[ 6000.300000] blk_update_request: I/O error, dev sdc, sector 8192 op 0x0:(READ) flags 0x0 phys_seg 1 prio class 0\n", "vmstat": "procs -----------memory---------- ---swap-- -----io---- -system-- -------cpu-------\n r  b   swpd   free   buff  cache   si   so    bi    bo   in   cs us sy id wa st gu\n 1  6      0  98000  23456 987654    0    0 52000  1200 1100 2200  4  3 38 55  0  0\n 0  7      0  97000  23456 987654    0    0 49000  1300 1000 2100  3  2 36 59  0  0\n"}], "expected": {"cause": "iowait", "evidence": ["vmstat"], "fix": "run-iostat-find-device"}}, {"args": [{"dmesg": "[ 6000.100000] blk_update_request: I/O error, dev sdb, sector 2048 op 0x0:(READ) flags 0x0 phys_seg 1 prio class 0\n[ 6000.200000] blk_update_request: I/O error, dev sdb, sector 4096 op 0x0:(READ) flags 0x0 phys_seg 1 prio class 0\n[ 6000.300000] Buffer I/O error on dev sdb1, logical block 512, async page read\n[ 6000.400000] blk_update_request: I/O error, dev sdb, sector 8192 op 0x1:(WRITE) flags 0x800 phys_seg 1 prio class 0\n[ 5000.100000] nfs: server nfs01 not responding, still trying\n[ 5060.200000] nfs: server nfs01 OK\n", "vmstat": "procs -----------memory---------- ---swap-- -----io---- -system-- ------cpu-----\n r  b   swpd   free   buff  cache   si   so    bi    bo   in   cs us sy id wa st\n 9  0      0 123456  23456 987654    0    0     5    20 9100 8200 55 12 10  1 22\n 8  0      0 123400  23456 987654    0    0     0    16 9200 8300 51 14  8  1 26\n"}], "expected": {"cause": "disk_error", "evidence": ["dmesg"], "fix": "replace-disk-check-raid"}}, {"args": [{"dmesg": "[ 6000.100000] blk_update_request: I/O error, dev sdc, sector 2048 op 0x0:(READ) flags 0x0 phys_seg 1 prio class 0\n[ 6000.200000] blk_update_request: I/O error, dev sdd, sector 4096 op 0x0:(READ) flags 0x0 phys_seg 1 prio class 0\n[ 6000.300000] blk_update_request: I/O error, dev sdc, sector 8192 op 0x0:(READ) flags 0x0 phys_seg 1 prio class 0\n", "vmstat": "procs -----------memory---------- ---swap-- -----io---- -system-- ------cpu-----\n r  b   swpd   free   buff  cache   si   so    bi    bo   in   cs us sy id wa st\n 9  0      0 123456  23456 987654    0    0     5    20 9100 8200 55 12 10  1 22\n 8  0      0 123400  23456 987654    0    0     0    16 9200 8300 51 14  8  1 26\n"}], "expected": {"cause": "cpu_steal", "evidence": ["vmstat"], "fix": "migrate-vms-or-reduce-overcommit"}}, {"args": [{"dmesg": "[ 5000.100000] nfs: server nfs01 not responding, still trying\n[ 5060.200000] nfs: server nfs01 OK\n", "vmstat": "procs -----------memory---------- ---swap-- -----io---- -system-- -------cpu-------\n r  b   swpd   free   buff  cache   si   so    bi    bo   in   cs us sy id wa st gu\n 1  6      0  98000  23456 987654    0    0 52000  1200 1100 2200  4  3 38 55  0  0\n 0  7      0  97000  23456 987654    0    0 49000  1300 1000 2100  3  2 36 59  0  0\n"}], "expected": {"cause": "iowait", "evidence": ["vmstat"], "fix": "run-iostat-find-device"}}, {"args": [{"vmstat": "procs -----------memory---------- ---swap-- -----io---- -s